import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'compliance-store',
  description:
    "Read and update the compliance register (obligations.json) and its evidence log (evidence.json). action:'status' for what is overdue and due soon; 'add' to record an obligation (an existing title is updated, never duplicated); 'complete' when one is done (a recurring one rolls to its next due date); 'set_status' to mark one in progress; 'log_evidence' to file proof; 'list' for the whole register.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add', 'complete', 'set_status', 'log_evidence', or 'list'.",
      required: true,
    },
    id: { type: 'string', description: "Obligation id, e.g. 'ob-3'." },
    title: {
      type: 'string',
      description: "The obligation's name, e.g. 'Food service permit'. Also finds it when no id is given.",
    },
    category: {
      type: 'string',
      description: 'license, permit, filing, insurance, certification, inspection, policy, or other.',
    },
    dueAt: { type: 'string', description: 'The next due date, YYYY-MM-DD.' },
    recurs: { type: 'string', description: 'none, monthly, quarterly, or yearly.' },
    owner: { type: 'string', description: 'Who is responsible.' },
    authority: { type: 'string', description: 'Who issues or checks it, e.g. County Health Department.' },
    status: { type: 'string', description: 'For set_status: open or in-progress.' },
    note: { type: 'string', description: 'What happened, with any reference number exactly as written.' },
    file: { type: 'string', description: "Workspace path of an evidence file, e.g. 'evidence/permit-2026.pdf'." },
    withinDays: { type: 'number', description: 'How many days ahead counts as due soon (default 60).' },
  },
  outputs: {
    overdue: { type: 'number', description: 'Open obligations past their due date.' },
    dueSoon: { type: 'number', description: 'Open obligations due within the window.' },
    tracked: { type: 'number', description: 'Obligations on the register.' },
    summary: { type: 'string', description: 'The register picture, or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write', 'reminders'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── compliance-rules-start ──
// Pure derivations: days left in local calendar days, the next due date of a
// recurring obligation, and the register line the crew reads. Kept
// self-contained between these sentinels so unit tests execute the shipped
// bytes.
var DAY_MS = 86400000;
var CATEGORIES = ['license', 'permit', 'filing', 'insurance', 'certification', 'inspection', 'policy', 'other'];
var RECURS = ['none', 'monthly', 'quarterly', 'yearly'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  var parsed = Date.parse(raw);
  return isFinite(parsed) ? localDay(parsed) : null;
}
function daysLeft(dueAt, nowMs) {
  var due = Date.parse(String(dueAt).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function rollForward(dueAt, recurs) {
  var months = recurs === 'monthly' ? 1 : recurs === 'quarterly' ? 3 : recurs === 'yearly' ? 12 : 0;
  if (!months) return null;
  var d = new Date(String(dueAt).slice(0, 10) + 'T12:00:00');
  var day = d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() + months);
  // The 31st of a month rolls to the last day of a shorter one, not into the next.
  var last = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
  d.setDate(Math.min(day, last));
  return localDay(d.getTime());
}
function when(days) {
  if (days < 0) return -days + (days === -1 ? ' day late' : ' days late');
  if (days === 0) return 'due today';
  return 'in ' + days + (days === 1 ? ' day' : ' days');
}
function proofOf(record, events) {
  return events.filter(function (e) {
    return e.data && e.data.obligationId === record.id;
  });
}
function line(record, events, nowMs) {
  var f = record.fields || {};
  var proof = proofOf(record, events);
  var last = proof.length ? proof[proof.length - 1] : null;
  return (
    f.title +
    ' (' + record.id + ', ' + (f.category || 'other') + ', owner ' + (f.owner || 'unassigned') + ') ' +
    when(daysLeft(f.dueAt, nowMs)) + ', due ' + f.dueAt +
    (record.status === 'in-progress' ? ', in progress' : '') +
    (f.recurs && f.recurs !== 'none' ? ', ' + f.recurs : '') +
    '; ' + (last ? 'last proof ' + String(last.at).slice(0, 10) + ': ' + (last.note || last.data.file) : 'no proof on file')
  );
}
function picture(records, events, nowMs, withinDays) {
  var open = records.filter(function (r) {
    return r.status !== 'done' && r.fields && r.fields.dueAt;
  });
  var byDue = function (a, b) {
    return String(a.fields.dueAt).localeCompare(String(b.fields.dueAt));
  };
  var overdue = open.filter(function (r) { return daysLeft(r.fields.dueAt, nowMs) < 0; }).sort(byDue);
  var soon = open
    .filter(function (r) {
      var d = daysLeft(r.fields.dueAt, nowMs);
      return d >= 0 && d <= withinDays;
    })
    .sort(byDue);
  var later = open.filter(function (r) { return daysLeft(r.fields.dueAt, nowMs) > withinDays; }).sort(byDue);
  var parts = [records.length + (records.length === 1 ? ' obligation' : ' obligations') + ' on the register, ' + overdue.length + ' overdue.'];
  // One list, overdue first: asked "what's due in 60 days", a model read a separate overdue list as out of scope.
  var due = overdue.concat(soon);
  parts.push(
    due.length
      ? 'Due within ' + withinDays + ' days, overdue first: ' + due.map(function (r) { return line(r, events, nowMs); }).join(' | ') + '.'
      : 'Nothing due in the next ' + withinDays + ' days.',
  );
  if (later.length) parts.push('Next after that: ' + later[0].fields.title + ', due ' + later[0].fields.dueAt + '.');
  return { overdue: overdue.length, dueSoon: soon.length, summary: parts.join(' ') };
}
// ── compliance-rules-end ──

const obligations = rosterStore(gezel.fs, 'obligations.json', {
  stages: ['open', 'in-progress', 'done'],
  idPrefix: 'ob',
});
const evidence = logStore(gezel.fs, 'evidence.json');

async function resolve(): Promise<string> {
  if (input.id) return input.id;
  if (input.title) {
    const wanted = input.title.trim().toLowerCase();
    const all = await obligations.list();
    const exact = all.filter((r) => String(r.fields.title ?? '').toLowerCase() === wanted);
    if (exact.length === 1) return exact[0]!.id;
    const partial = all.filter((r) => String(r.fields.title ?? '').toLowerCase().includes(wanted));
    if (partial.length === 1) return partial[0]!.id;
    if (partial.length > 1) {
      throw new Error("More than one obligation matches '" + input.title + "': " + partial.map((r) => r.id + ' ' + String(r.fields.title)).join(', ') + '. Pass id.');
    }
  }
  throw new Error("Pass 'id' (e.g. 'ob-3') or the obligation's 'title'. Call action:'list' to see them.");
}

// The register's one reminder sits on the soonest open obligation, 14 days ahead of it.
async function remindNextDue(): Promise<void> {
  const now = Date.now();
  const lead = 14 * DAY_MS;
  const next = (await obligations.list())
    .filter((r) => r.status !== 'done' && typeof r.fields.dueAt === 'string')
    .map((r) => ({ title: String(r.fields.title), dueAt: String(r.fields.dueAt), at: Date.parse(String(r.fields.dueAt) + 'T09:00:00') - lead }))
    .filter((r) => r.at > now)
    .sort((a, b) => a.at - b.at)[0];
  try {
    if (!next || next.at - now > 30 * DAY_MS) await gezel.reminder.clear();
    else await gezel.reminder.set({ at: new Date(next.at).toISOString(), title: next.title + ' is due in two weeks', body: 'Due ' + next.dueAt + '. Open the register to plan it.' });
  } catch {
    // Reminders are a convenience; the register is the record.
  }
}

const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 60;
let note = '';

if (input.action === 'add') {
  if (!input.title) throw new Error("add needs 'title'.");
  const dueAt = input.dueAt ? normalizeDate(input.dueAt) : null;
  if (input.dueAt && !dueAt) throw new Error("dueAt must be a date, e.g. '2026-12-01'.");
  const category = CATEGORIES.includes(String(input.category)) ? String(input.category) : undefined;
  const recurs = RECURS.includes(String(input.recurs)) ? String(input.recurs) : undefined;
  const wanted = input.title.trim().toLowerCase();
  const existing = (await obligations.list()).find((r) => String(r.fields.title ?? '').toLowerCase() === wanted);
  const fields: Record<string, unknown> = {
    ...(dueAt ? { dueAt } : {}),
    ...(category ? { category } : {}),
    ...(recurs ? { recurs } : {}),
    ...(input.owner ? { owner: input.owner.trim() } : {}),
    ...(input.authority ? { authority: input.authority.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  if (existing) {
    await obligations.update(existing.id, { fields });
    note = 'Updated ' + String(existing.fields.title) + '.';
  } else {
    if (!dueAt) throw new Error("A new obligation needs 'dueAt' (YYYY-MM-DD).");
    const record = await obligations.add({
      status: 'open',
      fields: { title: input.title.trim(), category: category ?? 'other', recurs: recurs ?? 'none', ...fields },
    });
    note = 'Added ' + record.id + '.';
  }
} else if (input.action === 'complete') {
  const id = await resolve();
  const record = await obligations.get(id);
  if (!record) throw new Error('No obligation ' + id + '.');
  await evidence.append({
    kind: 'completed',
    note: input.note ?? 'Completed.',
    data: { obligationId: id, ...(input.file ? { file: input.file } : {}) },
  });
  const next = rollForward(String(record.fields.dueAt ?? ''), String(record.fields.recurs ?? 'none'));
  if (next) {
    await obligations.update(id, { fields: { dueAt: next, lastCompletedAt: localDay(Date.now()) } });
    if (record.status !== 'open') await obligations.transition(id, 'open', { note: 'Completed; next due ' + next });
    note = String(record.fields.title) + ' completed; next due ' + next + '.';
  } else {
    await obligations.transition(id, 'done', { note: input.note ?? 'Completed' });
    note = String(record.fields.title) + ' completed.';
  }
} else if (input.action === 'set_status') {
  if (input.status !== 'open' && input.status !== 'in-progress') throw new Error("set_status needs status 'open' or 'in-progress'.");
  const id = await resolve();
  await obligations.transition(id, input.status, input.note ? { note: input.note } : {});
} else if (input.action === 'log_evidence') {
  if (!input.note && !input.file) throw new Error("log_evidence needs 'note' or 'file'.");
  const id = await resolve();
  await evidence.append({
    kind: 'evidence',
    note: input.note ?? 'Filed ' + input.file + '.',
    data: { obligationId: id, ...(input.file ? { file: input.file } : {}) },
  });
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, add, complete, set_status, log_evidence, or list.");
}

const records = await obligations.list();
const events = await evidence.list();
const now = Date.now();
const view = picture(records, events, now, withinDays);
await remindNextDue();

gezel.output({
  overdue: view.overdue,
  dueSoon: view.dueSoon,
  tracked: records.length,
  summary:
    input.action === 'list'
      ? records.map((r) => '[' + r.status + '] ' + line(r, events, now)).join('\n') || 'The register is empty.'
      : (note ? note + ' ' : '') + view.summary,
});

reaction.prompt:
The person just recorded a completion on the register page. The register now reads (its first sentence is what changed):
{{output.summary}}
In two short sentences, confirm what changed, including the next due date if it recurs, and name the next item to plan. Do not call tools.
